// Some portions generated by Claude
/**
 * The explorer's own queries (what the user asked for, and the labels and types of what is drawn) go first: the
 * Filters panel's background loading waits until none of them is running. Browsers allow six connections per
 * server, so background requests that start meanwhile would make the user's query wait.
 */
export function foregroundTracker() {
  let active = 0;
  let waiting: Array<() => void> = [];
  return {
    track<T>(work: Promise<T>): Promise<T> {
      active++;
      return work.finally(() => {
        active--;
        if (active) return;
        const ready = waiting;
        waiting = [];
        ready.forEach((resolve) => resolve());
      });
    },
    idle(): Promise<void> {
      return active ? new Promise((resolve) => waiting.push(resolve)) : Promise.resolve();
    },
  };
}
